package qa.domain;
import domain.bestiarium.physical_plane.ferae.*; import domain.bestiarium.interstice.faerie.*; import domain.character.*; import domain.metaprogression.*; import domain.persona.*; import domain.combat.PhysicalDamage; import java.util.*;
public final class BestiaryPersonaAndMetaprogressionVerification { @org.junit.jupiter.api.Test
    @org.junit.jupiter.api.Tag("domain")
        void verifiesCanonicalContract(){org.junit.jupiter.api.Assertions.assertTrue(FeraeCatalog.all().size()>=33,"Debe existir el catálogo Ferae completo.");org.junit.jupiter.api.Assertions.assertTrue(FeraeCatalog.canonicalTrophies().size()==15,"Deben existir quince trofeos.");PersonaProfile p=new PersonaProfile("x","Kenan",Gender.HOMBRE,CharacterClass.INDOMITO,198,List.of(),List.of());TravelCompanionState c=new TravelCompanionState();var ctx=new domain.ability.AnimalEmpathyContext(true,domain.ability.MasteryKnowledgeState.UNLOCKED,999,999,java.util.EnumSet.allOf(HuntingTrophy.class),true);c.bond(FeraeSpecies.RATON,p,ctx);c.bond(FeraeSpecies.PERRO,p,ctx);org.junit.jupiter.api.Assertions.assertTrue(c.active().orElseThrow()==FeraeSpecies.PERRO,"El segundo compañero sustituye al primero.");var r=new DoppelgangerDamagePolicy().transmute(new PhysicalDamage(30,20,50),80,25,0);org.junit.jupiter.api.Assertions.assertTrue(r.rawFrenzy()==180&&r.curseDamage()==25,"La Maldición no debe transmutarse.");}}
